import org.rabochaya.projects.*;import org.w3c.dom.*;import javax.xml.parsers.*;import java.io.*;import java.util.*;
public final class ObjectConfirmationDraftTests {
 static int checks;static void check(boolean v){checks++;if(!v)throw new AssertionError("confirmation "+checks);}static void bad(Runnable r){boolean rejected=false;try{r.run();}catch(IllegalArgumentException e){rejected=true;}check(rejected);}
 public static void main(String[] args)throws Exception{
  DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);Element root=f.newDocumentBuilder().parse(new ByteArrayInputStream("<Document xmlns='http://www.opengis.net/kml/2.2'><Folder><name>Target</name><Folder><name>Child folder</name></Folder></Folder><Placemark><name>Point</name></Placemark><Placemark><name>Other</name></Placemark></Document>".getBytes("UTF-8"))).getDocumentElement();String token=ObjectTree.token(root),stamp="a".repeat(64);List<ObjectTree.Row> rows=ObjectTree.rows(root);
  for(String action:new String[]{"delete","show","hide","pastecopy","pastecut"}){boolean paste=action.startsWith("paste");ObjectConfirmationDraft d=ObjectConfirmationDraft.capture(7,action,token,"s",rows,Arrays.asList("1","2"),paste?"0":"",paste?"Root / Target":"",paste?stamp:"","Title","Original preview",1);check(d.restore(7,root,"s",stamp).equals(Arrays.asList("1","2")));check(d.action.equals(action)&&d.token.equals(token)&&d.message.equals("Original preview"));check(d.restore(8,root,"s",stamp).isEmpty());check(d.restore(7,root,"other",stamp).isEmpty());check(d.restore(7,null,"s",stamp).isEmpty());check(d.restore(7,root,null,stamp).isEmpty());int[] indices=d.indices();indices[0]=9999;check(d.restore(7,root,"s",stamp).size()==2);if(paste){check(d.restore(7,root,"s","b".repeat(64)).isEmpty());check(d.restore(7,root,"s",null).isEmpty());}}
  ObjectConfirmationDraft full=ObjectConfirmationDraft.capture(7,"show",token,"s",rows,Arrays.asList("0","0/0"),"","","","Show","2 own flags",0);check(full.restore(7,root,"s",null).equals(Arrays.asList("0","0/0")));check(ObjectTree.token(root).equals(token));
  for(String destination:new String[]{"1","999","0/0"}){String source=destination.equals("0/0")?"0":"1";check(ObjectConfirmationDraft.capture(7,"pastecopy",token,"s",rows,Arrays.asList(source),destination,"Target",stamp,"Paste","Preview",0).restore(7,root,"s",stamp).isEmpty());}
  int[] input={2};ObjectConfirmationDraft defensive=new ObjectConfirmationDraft(7,"delete",token,"s",input,"","","","Delete","Preview",0);input[0]=999;check(defensive.restore(7,root,"s",null).equals(Arrays.asList("1")));
  for(int[] invalid:new int[][]{{},{-1},{10000},{2,2},new int[10001]})bad(()->new ObjectConfirmationDraft(7,"delete",token,"s",invalid,"","","","Delete","Preview",0));
  bad(()->new ObjectConfirmationDraft(0,"delete",token,"s",new int[]{2},"","","","Delete","Preview",0));bad(()->new ObjectConfirmationDraft(7,"save",token,"s",new int[]{2},"","","","Delete","Preview",0));bad(()->new ObjectConfirmationDraft(7,"delete",null,"s",new int[]{2},"","","","Delete","Preview",0));bad(()->new ObjectConfirmationDraft(7,"delete",token,"",new int[]{2},"","","","Delete","Preview",0));bad(()->new ObjectConfirmationDraft(7,"delete",token,"s",new int[]{2},"0","","","Delete","Preview",0));bad(()->new ObjectConfirmationDraft(7,"pastecopy",token,"s",new int[]{2},"0","Target","bad","Paste","Preview",0));bad(()->new ObjectConfirmationDraft(7,"pastecopy",token,"s",new int[]{2},"../0","Target",stamp,"Paste","Preview",0));bad(()->new ObjectConfirmationDraft(7,"delete",token,"s",new int[]{2},"","","","Delete","x".repeat(45001),0));
  root.insertBefore(ObjectTree.resolve(root,"2"),ObjectTree.resolve(root,"1"));check(full.restore(7,root,"s",null).isEmpty());check(full.token.equals(token));
  System.out.println("PASS ObjectConfirmationDraft: "+checks+" assertions");
 }
}
